import{_ as i,c as a,o as t,aj as o}from"./chunks/framework.7GHUzdv_.js";const g=JSON.parse('{"title":"Language Specification","description":"","frontmatter":{},"headers":[],"relativePath":"spec.md","filePath":"spec.md","lastUpdated":1768672518000}'),r={name:"spec.md"};function n(s,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="language-specification" tabindex="-1">Language Specification <a class="header-anchor" href="#language-specification" aria-label="Permalink to “Language Specification”">​</a></h1><p>The complete RizzScript language specification.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p><strong>RizzScript</strong> is a utility-focused, esoteric scripting language optimized for:</p><ul><li>Asynchronous task creation and handling</li><li>HTTP/TCP request/response operations</li><li>Fast I/O operations</li><li>SIMD-accelerated JSON parsing</li><li>High-performance regex parsing</li></ul><p><strong>Execution</strong>: Interpreted runtime (like Python)</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rizz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script.rizz</span></span></code></pre></div><h2 id="core-philosophy" tabindex="-1">Core Philosophy <a class="header-anchor" href="#core-philosophy" aria-label="Permalink to “Core Philosophy”">​</a></h2><ul><li><strong>Functional Programming Paradigm</strong>: First-class functions, immutability encouraged</li><li><strong>Esoteric but Intuitive</strong>: Urban slang keywords that are memorable and expressive</li><li><strong>Utility-First</strong>: Built-in primitives for common async/networking/IO tasks</li><li><strong>Performance-Oriented</strong>: SIMD operations and optimized parsers under the hood</li></ul><h2 id="data-types" tabindex="-1">Data Types <a class="header-anchor" href="#data-types" aria-label="Permalink to “Data Types”">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>int</code></td><td>Integer numbers</td><td><code>42</code>, <code>-10</code></td></tr><tr><td><code>float</code></td><td>Floating-point numbers</td><td><code>3.14</code>, <code>-0.5</code></td></tr><tr><td><code>char</code></td><td>Single character</td><td><code>&#39;a&#39;</code>, <code>&#39;z&#39;</code></td></tr><tr><td><code>string</code></td><td>Text sequences</td><td><code>&quot;Hello World&quot;</code></td></tr><tr><td><code>object</code></td><td>Key-value store</td><td><code>{&quot;name&quot;: &quot;rizz&quot;, &quot;age&quot;: 21}</code></td></tr><tr><td><code>array</code></td><td>Ordered collections</td><td><code>[1, 2, 3, &quot;yo&quot;]</code></td></tr></tbody></table><h2 id="keywords-syntax" tabindex="-1">Keywords &amp; Syntax <a class="header-anchor" href="#keywords-syntax" aria-label="Permalink to “Keywords &amp; Syntax”">​</a></h2><p>See the <a href="/rizz/syntax.html">Syntax &amp; Keywords</a> page for detailed documentation.</p><h2 id="operators" tabindex="-1">Operators <a class="header-anchor" href="#operators" aria-label="Permalink to “Operators”">​</a></h2><h3 id="arithmetic" tabindex="-1">Arithmetic <a class="header-anchor" href="#arithmetic" aria-label="Permalink to “Arithmetic”">​</a></h3><ul><li><code>+</code> Addition / String concatenation</li><li><code>-</code> Subtraction</li><li><code>*</code> Multiplication</li><li><code>/</code> Division</li><li><code>%</code> Modulo</li></ul><h3 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to “Comparison”">​</a></h3><ul><li><code>==</code> Equal</li><li><code>!=</code> Not equal</li><li><code>&gt;</code> Greater than</li><li><code>&lt;</code> Less than</li><li><code>&gt;=</code> Greater or equal</li><li><code>&lt;=</code> Less or equal</li></ul><h3 id="logical" tabindex="-1">Logical <a class="header-anchor" href="#logical" aria-label="Permalink to “Logical”">​</a></h3><ul><li><code>&amp;&amp;</code> AND</li><li><code>||</code> OR</li><li><code>!</code> NOT</li></ul><h3 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to “Assignment”">​</a></h3><ul><li><code>=</code> Assign</li></ul><h2 id="complete-specification" tabindex="-1">Complete Specification <a class="header-anchor" href="#complete-specification" aria-label="Permalink to “Complete Specification”">​</a></h2><p>For the full language specification, see <a href="https://github.com/rizz-script/rizz/blob/main/SPEC.md" target="_blank" rel="noreferrer">SPEC.md</a> in the repository.</p><p>The specification includes:</p><ul><li>Detailed syntax rules</li><li>Type system</li><li>Runtime behavior</li><li>Built-in functions</li><li>Standard library</li><li>Error handling semantics</li></ul><h2 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to “Version”">​</a></h2><p>Current version: <strong>v0.1</strong></p><h2 id="future-considerations" tabindex="-1">Future Considerations <a class="header-anchor" href="#future-considerations" aria-label="Permalink to “Future Considerations”">​</a></h2><h3 id="potential-additions" tabindex="-1">Potential Additions <a class="header-anchor" href="#potential-additions" aria-label="Permalink to “Potential Additions”">​</a></h3><ul><li><strong>Module system</strong>: <code>Bring &quot;http&quot;</code> (import)</li><li><strong>Pattern matching</strong>: Enhanced conditionals</li><li><strong>Streams</strong>: For large file processing</li><li><strong>WebSocket support</strong>: Real-time communication</li><li><strong>Database primitives</strong>: Direct DB operations</li><li><strong>More data structures</strong>: Maps, Sets, Queues</li><li><strong>Parallel loops</strong>: <code>CrazyParallel</code> for SIMD operations</li></ul><h3 id="syntax-refinements" tabindex="-1">Syntax Refinements <a class="header-anchor" href="#syntax-refinements" aria-label="Permalink to “Syntax Refinements”">​</a></h3><ul><li><strong>Destructuring</strong>: <code>Ayo {name, age} = user</code></li><li><strong>Spread operators</strong>: <code>Ayo combined = [...arr1, ...arr2]</code></li><li><strong>Pipe operator</strong>: <code>data |&gt; parse |&gt; transform |&gt; save</code></li><li><strong>Anonymous functions</strong>: <code>Ayo add = (a, b) =&gt; a + b</code></li></ul>',33)])])}const u=i(r,[["render",n]]);export{g as __pageData,u as default};
